// Kicker streaming recommendations (backlog item 15): rank the available
// kickers for a given week by how generous their opponent's defense has been
// to opposing kickers over completed weeks.
//
// Data is generated by `npm run fetch:matchups` (scripts/buildMatchupRatings.ts)
// from Sleeper's free weekly kicker stat lines, scored with the standard
// kicker scoring documented in kickerGenerosity.2026.json (FG made 3, PAT
// made 1, FG missed -1). Rank 1 = the defense gives up the most fantasy
// points to opposing kickers (the best streaming target). Implemented from
// TraderApe's own data; the weekly "which kicker do I stream" question is
// the FantasyPros/Yahoo kicker-streamer use case, priced here on our own
// numbers.

import scheduleJson from '@/data/nflSchedule.2026.json';
import generosityJson from '@/data/kickerGenerosity.2026.json';
import { POOL } from '@/data/draftPool';

export type KickerMatchupLabel = 'favorable' | 'neutral' | 'tough';

export interface KickerMatchup {
  /** The bundled pool id of the streaming kicker (for keys). */
  kickerId: string;
  /** The streaming kicker's name. */
  name: string;
  /** The kicker's NFL team (canonical abbreviation). */
  team: string;
  /** This week's opponent (canonical abbreviation). */
  opponent: string;
  /** Avg fantasy pts the opponent's defense allowed to opposing kickers. */
  avgAllowed: number;
  /** 1 = most generous to opposing kickers (best streaming target). */
  rank: number;
  label: KickerMatchupLabel;
  /** The team's own kicker's avg fantasy points over completed weeks. */
  ownAvg: number;
}

interface ScheduleFile {
  season: number;
  weeks: Record<string, Array<[string, string]>>;
  generatedAt: string;
}

interface GenerosityFile {
  season: number;
  weeks: [number, number];
  scoring: string;
  teams: Record<
    string,
    { generosityAvg: number; generosityRank: number; ownAvg: number }
  >;
  generatedAt: string;
}

// JSON imports widen tuples to arrays; assert through unknown so the
// tuple types hold.
const SCHEDULE = scheduleJson as unknown as ScheduleFile;
const GENEROSITY = generosityJson as unknown as GenerosityFile;

function labelFor(rank: number): KickerMatchupLabel {
  // Same cutoffs as the weekly skill-position matchup rating and D/ST
  // streamers.
  if (rank <= 10) return 'favorable';
  if (rank >= 23) return 'tough';
  return 'neutral';
}

/** First and last completed week that fed the generosity averages. */
export function kickerGenerosityWeeksRange(): [number, number] {
  return GENEROSITY.weeks;
}

/**
 * The starting kicker (per the bundled draft pool) for each NFL team.
 * Teams whose kicker isn't in the pool fall back to a team-unit entry.
 */
export function startingKickers(
  pool = POOL,
): Map<string, { id: string; name: string; team: string }> {
  const byTeam = new Map<string, { id: string; name: string; team: string }>();
  for (const p of pool.players) {
    if (p.pos !== 'K' || p.depthChartOrder !== 1 || !p.team) continue;
    if (!byTeam.has(p.team)) {
      byTeam.set(p.team, { id: p.id, name: p.name, team: p.team });
    }
  }
  return byTeam;
}

/**
 * This week's streaming matchup for one team's kicker: the opponent from
 * the bundled schedule plus the opponent's defense's generosity rating to
 * opposing kickers. Null when the team has no game that week (bye), no
 * kicker in the pool, or no generosity data.
 */
export function getKickerMatchup(
  team: string | null | undefined,
  week: number | undefined,
  schedule: ScheduleFile = SCHEDULE,
  generosity: GenerosityFile = GENEROSITY,
  kickers: Map<string, { id: string; name: string; team: string }> = startingKickers(),
): KickerMatchup | null {
  if (!team || week === undefined) return null;
  const games = schedule.weeks[String(week)];
  const game = games?.find(([h, a]) => h === team || a === team);
  if (!game) return null;
  const kicker = kickers.get(team);
  if (!kicker) return null;
  const opponent = game[0] === team ? game[1] : game[0];
  const entry = generosity.teams[opponent];
  if (!entry) return null;
  return {
    kickerId: kicker.id,
    name: kicker.name,
    team,
    opponent,
    avgAllowed: entry.generosityAvg,
    rank: entry.generosityRank,
    label: labelFor(entry.generosityRank),
    ownAvg: generosity.teams[team]?.ownAvg ?? 0,
  };
}

/**
 * Rank the kickers available in `week` for streaming: every team with a
 * game that week and no generosity data gaps, excluding the ones already
 * rostered (matched by NFL team). Ordered by opponent generosity (best
 * target first), ties broken by the kicker's own completed-week average.
 */
export function rankKickerStreamers(
  week: number | undefined,
  rosteredTeams: ReadonlySet<string>,
  limit = 5,
  schedule: ScheduleFile = SCHEDULE,
  generosity: GenerosityFile = GENEROSITY,
  kickers: Map<string, { id: string; name: string; team: string }> = startingKickers(),
): KickerMatchup[] {
  if (week === undefined) return [];
  const seen = new Set<string>();
  const entries: KickerMatchup[] = [];
  for (const [h, a] of schedule.weeks[String(week)] ?? []) {
    for (const team of [h, a]) {
      if (seen.has(team)) continue;
      seen.add(team);
      if (rosteredTeams.has(team)) continue;
      const matchup = getKickerMatchup(team, week, schedule, generosity, kickers);
      if (matchup) entries.push(matchup);
    }
  }
  entries.sort((x, y) => x.rank - y.rank || y.ownAvg - x.ownAvg);
  return entries.slice(0, Math.max(0, limit));
}
